const BetArray = () => {
  const dispatch = useDispatch();

  // Access Redux state with useSelector
  const rpsbetitems   = useSelector(state => state.logic.rpsbetitems);
  const qsbetitems    = useSelector(state => state.logic.qsbetitems);
  const user_balance  = useSelector(state => state.auth.user.balance);
  const user_id       = useSelector(state => state.auth.user._id);
  const prompt        = useSelector(state => state.auth.user.prompt);
  const user_range    = useSelector(state => state.auth.user.range);
  const solPrice      = useSelector(state => state.logic.solPrice);
  const totalWagered  = useSelector(state => state.auth.user.totalWagered);

  // Local component states
  const [selectedTab, setSelectedTab] = useState(0);
  const [settingsPanelOpened, setSettingsPanelOpened] = useState(false);
  const [range, setRange] = useState([1, 100]);
  const [accumulativeProfit, setAccumulativeProfit] = useState([]);
  const [aiOn, setAiOn] = useState(false);
  const [alignment, setAlignment] = useState('IS');
  const [rank, setRank] = useState(null);
  const [showMore, setShowMore] = useState(false);
  const [isSliderDisabled, setIsSliderDisabled] = useState(false);
  const [debounceTimeoutId, setDebounceTimeoutId] = useState(null);

  // Refs for DOM and mounted state
  const settingsRef = useRef(null);
  const isMounted = useRef(true);

  // Example chart data – adjust as needed
  const chartData = {
    options: {
      chart: { animations: { enabled: false }, toolbar: { show: false }, zoom: { enabled: false } },
      grid: { show: false },
      tooltip: { enabled: false },
      fill: {
        type: 'gradient',
        gradient: {
          shade: 'light',
          gradientToColors: ['#8F7CC3'],
          shadeIntensity: 1,
          type: 'vertical',
          opacityFrom: 0.7,
          opacityTo: 0.9,
          stops: [0, 100, 100]
        }
      },
      stroke: { curve: 'smooth' },
      xaxis: { labels: { show: false }, axisTicks: { show: false }, axisBorder: { show: false } },
      yaxis: { labels: { show: false }, axisTicks: { show: false }, axisBorder: { show: false } }
    },
    series: [
      { name: 'Accumulative Profit', data: accumulativeProfit || [] }
    ],
  };

  // Example attached rooms fetch – replace with your real implementation
  const fetchAttachedRooms = useCallback(async () => {
    // Dummy implementation; replace with your actual fetch logic
    return [];
  }, []);

  // Lifecycle: on mount, compute rank and update AI status
  useEffect(() => {
    isMounted.current = true;
    (async () => {
      try {
        if (totalWagered) {
          const computedRank = await getRank(totalWagered);
          setRank(computedRank);
        }

        if (user_id) {
          // Replace these dummy values with real async calls:
          const qbotStatus = false; // e.g. await getQbot();
          const rooms = await fetchAttachedRooms();
          const isAttached = rooms.some(roomItem => roomItem.room === "CURRENT_ROOM_ID");

          if (isAttached) {
            setAiOn(true);
            setAlignment('RA');
          } else if (qbotStatus) {
            setAiOn(true);
            setAlignment('EL');
          } else {
            setAiOn(false);
            setAlignment('IS');
          }
        }
      } catch (err) {
        console.error('Error during mount:', err);
      }
    })();

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      isMounted.current = false;
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [user_id, totalWagered, fetchAttachedRooms]);

  // Compute accumulative profit from bet items
  useEffect(() => {
    let profit = 0;
    const items = qsbetitems || rpsbetitems || [];
    const reversedItems = [...items].reverse();
    const calculatedProfit = reversedItems.map(item => {
      // Insert your profit logic here; this dummy adds the bet_amount:
      profit += Number(item.bet_amount) || 0;
      return profit;
    });
    setAccumulativeProfit(calculatedProfit);
  }, [rpsbetitems, qsbetitems]);

  // Update range if user_range changes
  useEffect(() => {
    if (user_range && user_range.length === 2) {
      const [min, max] = user_range;
      setRange([min, max]);
    }
  }, [user_range]);

  // Close settings panel if clicking outside
  const handleClickOutside = (e) => {
    if (settingsRef.current && !settingsRef.current.contains(e.target)) {
      setSettingsPanelOpened(false);
    }
  };

  // Tab change handler
  const handleTabChange = (event, newValue) => {
    setSelectedTab(newValue);
  };

  // Debounce helper for slider changes
  function debounce(fn, delay) {
    return function (...args) {
      if (debounceTimeoutId) clearTimeout(debounceTimeoutId);
      const newTimeoutId = setTimeout(() => fn(...args), delay);
      setDebounceTimeoutId(newTimeoutId);
    };
  }

  const handleSliderChange = (event, newValue) => {
    setRange(newValue);
  };

  const debouncedHandleRangeChange = debounce(async (event, newValue) => {
    setIsSliderDisabled(true);
    // Call your updateBetRangeFunction and getUser actions here:
    await dispatch(updateBetRangeFunction(user_id, newValue));
    await dispatch(getUser());
    setIsSliderDisabled(false);
  }, 1000);

  const handleSliderChangeCommitted = (event, newValue) => {
    debouncedHandleRangeChange(event, newValue);
  };

  const handleSettingsIconClick = () => {
    setSettingsPanelOpened(prev => !prev);
  };

  const handleShowMoreToggle = () => {
    setShowMore(prev => !prev);
  };

  // Render your component (this example renders only the BetAmountInput)
  return (
    <Box sx={{ position: 'relative', width: '100%', mt: 4 }}>
      <BetAmountInput 
        bet_amount={0}
        handle2xButtonClick={() => {}}
        handleHalfXButtonClick={() => {}}
        handleMaxButtonClick={() => {}}
        onChangeState={() => {}}
        isDarkMode={false}
        bankroll={0}
      />
      {/* Additional UI components (such as tabs, charts, or SettingsRef) can be rendered here */}
    </Box>
  );
};

